class ContaBancaria:
    def __init__(self, titular: str, saldo: float = 0.0):
        self.titular = titular
        self.saldo = saldo

    def depositar(self, valor: float) -> None:
        self.saldo += valor

conta = ContaBancaria("Ana", 100.0)
conta.depositar(50.0)
print(conta.saldo)  # 150.0

